     return app.applyMoveAnimated(loc, mv.destZone, mv.destIndex).ok;
   }

   /** アニメーション付きで1手ずつ再生する(250ms待機を挟む)。完了後に全手順パネル表示 */
   function startAnimatedReplay(moves) {
     if (!moves || moves.length === 0) {
       finishAutoSolve();
       return;
     }
     replayMoves = moves;
     replayIndex = 0;
     // 自動ホーム送りは無効化してソルバーの手順通りに進める（元の設定を保存）
