    activeRequest = { requestId, snapshot: boardSnapshot(board), autoPlay };
    if (autoPlay) {
      savedAutoMoveEnabled = app.getAutoMoveEnabled();
    }
    setBusy(true);
    if (autoPlay) {
      autoSolving = true;
      app.setAutoSolving(true);
      const toggle = document.getElementById("auto-solve-toggle");
      if (toggle) {
        toggle.checked = true;
      }
    }
    worker = new Worker(...);
