}
```

New flow per 4.3:

```js
/** キャッシュから供給できる残り手順(防御チェック済み)を返す。供給不可なら null */
function cachedRemainingMoves() {
  if (!cacheEntry) {
    return null;
  }
  const board = boardFromState();
  const j = findProgressIndex(cacheEntry, board);
  if (j < 0) {
    cacheEntry = null; // パス外の盤面 → 破棄
    return null;
  }
  if (j === cacheEntry.boards.length - 1) {
    // 勝利盤面は供給対象外 → 破棄
    cacheEntry = null;
    return null;
